<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue'

let deferredInstallPrompt: (Event & { prompt: () => Promise<void> }) | null = null
if (typeof window !== 'undefined') window.addEventListener('beforeinstallprompt', (event) => { event.preventDefault(); deferredInstallPrompt = event as Event & { prompt: () => Promise<void> } })
async function installPwa() {
  const ios = /iPhone|iPad|iPod/.test(navigator.userAgent) && !(navigator as Navigator & { standalone?: boolean }).standalone
  if (deferredInstallPrompt) { await deferredInstallPrompt.prompt(); deferredInstallPrompt = null }
  else if (ios) window.alert('Di Safari, tekan Bagikan lalu pilih Tambahkan ke Layar Utama.')
  else if (!window.matchMedia('(display-mode: standalone)').matches) window.alert('Gunakan menu browser lalu pilih Install Empati TB.')
  if ('Notification' in window && Notification.permission === 'default') await Notification.requestPermission()
}

// Remove decorative checklist from medication progress text.
type Notification = { id:number; title:string; message:string; is_read:boolean; created_at:string }
type CadrePatient = { id:number; full_name:string; phone:string; rt:string; rw:string; reports_today:number; not_taken_today:number }
type CadreSchedule = { id:number; full_name:string; control_date:string; start_time:string; status:string; treatment_place:string }
type PatientReport = { id:number; report_date:string; medication_taken:boolean; has_side_effect:boolean; side_effect_category:string|null; side_effect_description:string|null; status:string; scheduled_time:string|null }
type PatientSchedule = { id:number; control_date:string; start_time:string; status:string; purpose:string|null; treatment_place_name:string; treatment_place_address:string }
const user=JSON.parse(sessionStorage.getItem('tb_user')??'{}'),data=ref<Record<string, any>>({}),error=ref(''),active=ref('Beranda');const kader=user.role==='kader'
const notifications=ref<Notification[]>([])
const cadrePatients=ref<CadrePatient[]>([]),cadreSchedules=ref<CadreSchedule[]>([]),panel=ref('')
const patientReports=ref<PatientReport[]>([]),patientSchedules=ref<PatientSchedule[]>([]),patientPanel=ref('')
const cadreDailyPatients=ref<Record<string, any>[]>([]); const cadreReportDate=ref(new Date().toISOString().slice(0, 10))
const cadreDailySummary=ref({ total: 0, taken: 0, not_taken: 0, unreported: 0 })
const cadreMonitoringFilter=ref<'all'|'taken'|'unreported'>('all')
const selectedCadreDailyPatient=ref<Record<string, any>|null>(null)
const filteredCadreDailyPatients = computed(() => {
  if (cadreMonitoringFilter.value === 'taken') {
    return cadreDailyPatients.value.filter(item => item.daily_status === 'taken')
  }
  if (cadreMonitoringFilter.value === 'unreported') {
    return cadreDailyPatients.value.filter(item => item.daily_status !== 'taken')
  }
  return cadreDailyPatients.value
})
function openCadrePatientDetail(item: Record<string, any>) {
  selectedCadreDailyPatient.value = item
}
function closeCadrePatientDetail() {
  selectedCadreDailyPatient.value = null
}
const reportDialog=ref(false),reportStep=ref<'camera'|'effects'|'done'>('camera'),cameraVideo=ref<HTMLVideoElement|null>(null),cameraStream=ref<MediaStream|null>(null),cameraFacing=ref<'user'|'environment'>('environment'),cameraTimestamp=ref(''),reportPhoto=ref<Blob|null>(null),reportPhotoPreview=ref(''),hasSideEffect=ref<boolean|null>(null),sideEffectCategory=ref(''),sideEffectDescription=ref(''),reportError=ref(''),reportSaving=ref(false),sideEffectReportId=ref<number|null>(null),historySideEffectDialog=ref(false),historySideEffectCategory=ref(''),historySideEffectDescription=ref(''),historySideEffectError=ref(''),historySideEffectSaving=ref(false)
const patient = computed(() => data.value.patient ?? {})
const name = computed(() => patient.value.full_name ?? user.name ?? 'Pasien TB')
const initials = computed(() => name.value.split(' ').map((s:string)=>s[0]).slice(0,2).join(''))
const patientPhoto = computed(() => patient.value.photo_path ? `/media/profile/${patient.value.photo_path}` : '')
const patientHero = computed(() => patient.value.gender === 'P' ? '/illustrations/patient-woman-hero.png' : '/illustrations/patient-man-hero.png')
const nextControl = computed(() => data.value.next_control)
const medicationSchedules = computed<Record<string, any>[]>(() => data.value.medication_schedules ?? [])
const nextMedication = computed<Record<string, any> | null>(() => data.value.next_medication ?? null)
const medicationScheduleCount = computed(() => medicationSchedules.value.length)
const nextMedicationTime = computed(() => nextMedication.value?.time_of_day?.slice(0, 5) ?? nextMedication.value?.label ?? 'Belum ada jadwal')
const nextMedicationLabel = computed(() => nextMedication.value ? (nextMedication.value.medication_name === 'Obat belum ditentukan' ? 'Jadwal minum obat sesuai anjuran petugas' : `${nextMedication.value.medication_name} · ${nextMedication.value.dose} ${nextMedication.value.dose_unit ?? ''}`.trim()) : 'Belum ada jadwal obat')
const nextMedicationDateLabel = computed(() => nextMedication.value?.schedule_date ? formatDate(nextMedication.value.schedule_date) : 'Tanggal belum tersedia')
const medicationProgress = computed(() => medicationScheduleCount.value ? Math.round((Number(data.value.reports_today ?? 0) / medicationScheduleCount.value) * 100) : 0)
const hasReportedMedicationToday = computed(() => medicationScheduleCount.value > 0 && Number(data.value.reports_today ?? 0) >= medicationScheduleCount.value)
const statusLabels:Record<string,string>={submitted:'Terkirim',verified:'Terverifikasi',rejected:'Ditolak',follow_up:'Perlu tindak lanjut'}
const statusLabel=(status:string)=>statusLabels[status]??'Diproses'
const greeting = computed(() => new Date().getHours()<11?'Selamat datang,':'Selamat siang,')
const kaderName = computed(() => (user.name || 'Kader').split(' ')[0])
const cadreInitials = computed(() => (user.name || 'K').split(' ').map((word:string) => word[0]).slice(0, 2).join(''))
const cadrePhoto = computed(() => data.value.cadre?.photo_path ? `/media/profile/${data.value.cadre.photo_path}` : '')
const quickMenus = [
  { key:'patients', label:'Data Pasien', icon:'/icons/users-color.png', tone:'blue' }, { key:'monitoring', label:'Monitoring Minum Obat', icon:'/icons/pill-color.png', tone:'green' },
  { key:'schedules', label:'Jadwal Kontrol', icon:'/icons/calendar-color.png', tone:'pink' }, { key:'reports', label:'Laporan', icon:'/icons/chart-color.png', tone:'purple' },
  { key:'messages', label:'Pesan Pasien', icon:'/icons/notification-color.png', tone:'orange', badge:2 }, { key:'education', label:'Edukasi TB', icon:'/icons/alert-color.png', tone:'cyan' },
  { key:'information', label:'Info & Pengumuman', icon:'/icons/monitoring-tb.png', tone:'yellow' }, { key:'help', label:'Bantuan', icon:'/icons/settings-color.png', tone:'teal' },
]
const panelTitle = computed(() => quickMenus.find(item => item.key === panel.value)?.label || (panel.value === 'profile' ? 'Profil Kader' : ''))
const patientPanelTitle = computed(() => { const titles:Record<string,string>={medicine:'Minum Obat',profile:'Pengaturan',identity:'Data Pasien',history:'Riwayat Laporan',sideEffects:'Efek Samping',schedules:'Jadwal Kontrol',notifications:'Notifikasi',cadre:'Kader PMO'}; return titles[patientPanel.value] || '' })
async function fetchCadreDailyReports(dateString?: string) {
  if (dateString) cadreReportDate.value = dateString
  try {
    const base = import.meta.env.VITE_API_BASE_URL ?? 'http://127.0.0.1:8010/api/v1'
    const headers = { Authorization: `Bearer ${sessionStorage.getItem('tb_token')}`, Accept: 'application/json' }
    const res = await fetch(`${base}/kader/medication-reports/daily?date=${cadreReportDate.value}`, { headers })
    const payload = await res.json()
    if (res.ok && payload.data) {
      cadreDailyPatients.value = payload.data.patients ?? []
      cadreDailySummary.value = payload.data.summary ?? { total: 0, taken: 0, not_taken: 0, unreported: 0 }
    }
  } catch (e) {
    console.error(e)
  }
}
function openPanel(key:string){panel.value=key;active.value=key==='profile'?'Profil':quickMenus.find(item=>item.key===key)?.label||key;if(key==='reports'||key==='monitoring'){fetchCadreDailyReports()}}
function closePanel(){panel.value='';active.value='Beranda'}
function openPatientPanel(key:string){patientPanel.value=key;active.value=key==='medicine'?'Obat':key==='history'?'Riwayat Laporan':key==='schedules'?'Kontrol':key==='profile'?'Pengaturan':key}
function closePatientPanel(){patientPanel.value='';active.value='Beranda'}
function formatDate(value?:string|null){if(!value)return 'Tanggal tidak tersedia';const str=String(value).trim();const dmyMatch=str.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{4})/);if(dmyMatch){const [,d,m,y]=dmyMatch;const date=new Date(Number(y),Number(m)-1,Number(d));if(!Number.isNaN(date.getTime()))return date.toLocaleDateString('id-ID',{day:'2-digit',month:'short',year:'numeric'})}const ymdMatch=str.match(/^(\d{4})[/-](\d{1,2})[/-](\d{1,2})/);if(ymdMatch){const [,y,m,d]=ymdMatch;const date=new Date(Number(y),Number(m)-1,Number(d));if(!Number.isNaN(date.getTime()))return date.toLocaleDateString('id-ID',{day:'2-digit',month:'short',year:'numeric'})}const date=new Date(str);return Number.isNaN(date.getTime())?'Tanggal tidak tersedia':date.toLocaleDateString('id-ID',{day:'2-digit',month:'short',year:'numeric'})}
function formatTime(value?:string|null){if(!value)return '';const date=new Date(value);return Number.isNaN(date.getTime())?'':date.toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'})}
function formatCameraTimestamp(date=new Date()){return new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(date).replace(',', ' · ')+' WIB'}
function clearReportPhoto(){if(reportPhotoPreview.value)URL.revokeObjectURL(reportPhotoPreview.value);reportPhoto.value=null;reportPhotoPreview.value=''}
function stopCamera(){cameraStream.value?.getTracks().forEach(track=>track.stop());cameraStream.value=null;if(cameraVideo.value)cameraVideo.value.srcObject=null}
async function startCamera(){reportError.value='';cameraTimestamp.value=formatCameraTimestamp();stopCamera();try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('Kamera tidak didukung oleh perangkat ini.');cameraStream.value=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:cameraFacing.value},width:{ideal:1080},height:{ideal:1440}},audio:false});await nextTick();if(cameraVideo.value){cameraVideo.value.srcObject=cameraStream.value;await cameraVideo.value.play()}}catch(e){reportError.value=e instanceof Error?`Kamera tidak dapat dibuka: ${e.message}`:'Kamera tidak dapat dibuka. Gunakan unggah foto sebagai alternatif.'}}
function switchCamera(){cameraFacing.value=cameraFacing.value==='environment'?'user':'environment';startCamera()}
function openMedicationReport(){if(hasReportedMedicationToday.value)return;if(!nextMedication.value?.schedule_time_id){openPatientPanel('medicine');return}closePatientPanel();clearReportPhoto();hasSideEffect.value=null;sideEffectCategory.value='';sideEffectDescription.value='';reportError.value='';reportStep.value='camera';reportDialog.value=true;startCamera()}
function closeReportDialog(){stopCamera();clearReportPhoto();reportError.value='';reportDialog.value=false}
function capturePhoto(){const video=cameraVideo.value;if(!video?.videoWidth){reportError.value='Kamera belum siap. Tunggu sebentar lalu ambil foto.';return}const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');if(!ctx)return;const targetWidth=1080,targetHeight=1440,targetRatio=targetWidth/targetHeight,sourceRatio=video.videoWidth/video.videoHeight;let sourceX=0,sourceY=0,sourceWidth=video.videoWidth,sourceHeight=video.videoHeight;if(sourceRatio>targetRatio){sourceWidth=video.videoHeight*targetRatio;sourceX=(video.videoWidth-sourceWidth)/2}else{sourceHeight=video.videoWidth/targetRatio;sourceY=(video.videoHeight-sourceHeight)/2}canvas.width=targetWidth;canvas.height=targetHeight;ctx.drawImage(video,sourceX,sourceY,sourceWidth,sourceHeight,0,0,targetWidth,targetHeight);cameraTimestamp.value=formatCameraTimestamp();ctx.fillStyle='rgba(0, 0, 0, .58)';ctx.fillRect(0,targetHeight-92,targetWidth,92);ctx.fillStyle='#fff';ctx.font='600 30px Arial';ctx.fillText(`Bukti minum obat · ${cameraTimestamp.value}`,34,targetHeight-36);canvas.toBlob(blob=>{if(!blob){reportError.value='Foto gagal diproses. Coba ambil ulang.';return}clearReportPhoto();reportPhoto.value=blob;reportPhotoPreview.value=URL.createObjectURL(blob);stopCamera();reportStep.value='effects'},'image/jpeg',.9)}
function useSelectedPhoto(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;stopCamera();clearReportPhoto();reportPhoto.value=file;reportPhotoPreview.value=URL.createObjectURL(file);reportError.value='';reportStep.value='effects'}
function retakePhoto(){clearReportPhoto();reportStep.value='camera';startCamera()}
function currentPosition(){return new Promise<GeolocationPosition>((resolve,reject)=>{if(!navigator.geolocation){reject(new Error('Lokasi tidak didukung perangkat ini.'));return}navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:true,timeout:15000,maximumAge:0})})}
async function refreshPatientDashboard(){const base=import.meta.env.VITE_API_BASE_URL??'http://127.0.0.1:8010/api/v1',headers={Authorization:`Bearer ${sessionStorage.getItem('tb_token')}`,Accept:'application/json'};const [dashboardResponse,historyResponse]=await Promise.all([fetch(`${base}/me/dashboard`,{headers}),fetch(`${base}/me/medication/history?per_page=20`,{headers})]);const dashboardPayload=await dashboardResponse.json();if(!dashboardResponse.ok)throw new Error(dashboardPayload.message??'Gagal memperbarui dashboard.');data.value=dashboardPayload.data;const historyPayload=await historyResponse.json();if(historyResponse.ok)patientReports.value=historyPayload.data??[]}
async function submitMedicationReport(){if(!reportPhoto.value){reportError.value='Ambil atau unggah foto bukti terlebih dahulu.';return}if(hasSideEffect.value===null){reportError.value='Pilih jawaban mengenai efek samping terlebih dahulu.';return}if(hasSideEffect.value&&(!sideEffectCategory.value||!sideEffectDescription.value.trim())){reportError.value='Pilih kategori dan jelaskan efek samping yang dirasakan.';return}reportSaving.value=true;reportError.value='';try{const position=await currentPosition();const body=new FormData();body.append('schedule_time_id',String(nextMedication.value?.schedule_time_id));body.append('medication_taken','1');body.append('has_side_effect',hasSideEffect.value?'1':'0');body.append('photo',reportPhoto.value,'bukti-minum-obat.jpg');body.append('latitude',String(position.coords.latitude));body.append('longitude',String(position.coords.longitude));body.append('gps_accuracy',String(position.coords.accuracy));if(hasSideEffect.value){body.append('side_effect_category',sideEffectCategory.value);body.append('side_effect_description',sideEffectDescription.value.trim())}const response=await fetch(`${import.meta.env.VITE_API_BASE_URL??'http://127.0.0.1:8010/api/v1'}/me/medication/reports`,{method:'POST',headers:{Authorization:`Bearer ${sessionStorage.getItem('tb_token')}`,Accept:'application/json'},body});const payload=await response.json();if(!response.ok)throw new Error(payload.message??'Laporan minum obat gagal dikirim.');await refreshPatientDashboard();stopCamera();reportStep.value='done'}catch(e){reportError.value=e instanceof Error?e.message:'Laporan minum obat gagal dikirim.'}finally{reportSaving.value=false}}
function openHistorySideEffect(item:PatientReport){sideEffectReportId.value=item.id;historySideEffectCategory.value=item.side_effect_category??'';historySideEffectDescription.value=item.side_effect_description??'';historySideEffectError.value='';historySideEffectDialog.value=true}
function closeHistorySideEffect(){if(historySideEffectSaving.value)return;historySideEffectDialog.value=false;sideEffectReportId.value=null;historySideEffectError.value=''}
async function submitHistorySideEffect(){if(!historySideEffectCategory.value||!historySideEffectDescription.value.trim()){historySideEffectError.value='Pilih kategori dan jelaskan efek samping yang dirasakan.';return}historySideEffectError.value='';historySideEffectSaving.value=true;try{const response=await fetch(`${import.meta.env.VITE_API_BASE_URL??'http://127.0.0.1:8010/api/v1'}/me/medication/reports/${sideEffectReportId.value}/side-effect`,{method:'POST',headers:{Authorization:`Bearer ${sessionStorage.getItem('tb_token')}`,Accept:'application/json','Content-Type':'application/json'},body:JSON.stringify({category:historySideEffectCategory.value,description:historySideEffectDescription.value.trim()})});const payload=await response.json();if(!response.ok)throw new Error(payload.message??'Gagal mengirim laporan efek samping.');await refreshPatientDashboard();historySideEffectDialog.value=false;sideEffectReportId.value=null}catch(e){historySideEffectError.value=e instanceof Error?e.message:'Gagal mengirim laporan.'}finally{historySideEffectSaving.value=false}}
onMounted(async()=>{try{const base=import.meta.env.VITE_API_BASE_URL??'http://127.0.0.1:8010/api/v1';const headers={Authorization:`Bearer ${sessionStorage.getItem('tb_token')}`,Accept:'application/json'};const [dashboardResponse,notificationResponse,patientResponse,scheduleResponse]=await Promise.all([fetch(`${base}${kader?'/kader/dashboard':'/me/dashboard'}`,{headers}),fetch(`${base}/notifications?per_page=5`,{headers}),fetch(`${base}${kader?'/kader/patients':'/me/medication/history?per_page=20'}`,{headers}),fetch(`${base}${kader?'/kader/control-schedules':'/me/control-schedules'}`,{headers})]);const payload=await dashboardResponse.json();if(!dashboardResponse.ok)throw new Error(payload.message);data.value=payload.data;const notificationPayload=await notificationResponse.json();if(notificationResponse.ok)notifications.value=notificationPayload.data??[];const patientPayload=await patientResponse.json();const schedulePayload=await scheduleResponse.json();if(kader){if(patientResponse.ok)cadrePatients.value=patientPayload.data??[];if(scheduleResponse.ok)cadreSchedules.value=schedulePayload.data??[]}else{if(patientResponse.ok)patientReports.value=patientPayload.data??[];if(scheduleResponse.ok)patientSchedules.value=schedulePayload.data??[]}}catch(e){error.value=e instanceof Error?e.message:'Gagal memuat dashboard.'}})
onBeforeUnmount(()=>{stopCamera();clearReportPhoto()})
function logout(){sessionStorage.removeItem('tb_token');sessionStorage.removeItem('tb_user');window.location.href='/' }
</script>
<template>
  <main v-if="!kader" class="user-reference patient-dashboard">
    <header class="patient-header">
      <div class="patient-brand"><img src="/icons/icon-512.png" alt="Empati TB"/><div><b>Empati <em>TB</em></b><small>Puskesmas Sehat Bersama</small></div></div>
      <button type="button" class="patient-bell" aria-label="Notifikasi" @click="openPatientPanel('notifications')"><img src="/icons/notification-color.png" alt=""/><i>{{notifications.length}}</i></button>
      <button type="button" class="patient-avatar" aria-label="Profil" @click="openPatientPanel('profile')"><img v-if="patientPhoto" class="patient-avatar-photo" :src="patientPhoto" alt="Foto pasien"><template v-else>{{ initials }}</template></button>
    </header>
    <section class="patient-main">
      <section class="patient-welcome"><div class="patient-welcome-copy"><p>{{ greeting }}</p><h1>{{ name }}</h1><span>●&nbsp; Pasien Aktif</span><small>Tetap semangat jalani pengobatan!<br/>Bersama kita bisa sembuh dari TB.</small></div><img class="patient-welcome-figure patient-welcome-photo" :src="patientPhoto || patientHero" :alt="patientPhoto ? 'Foto pasien' : (patient.gender === 'P' ? 'Ilustrasi pasien perempuan' : 'Ilustrasi pasien laki-laki')"/></section>
      <article class="patient-install"><img src="/icons/icon-512.png" alt=""/><div><b>Instal aplikasi agar lebih mudah diakses</b><p>Dapatkan akses lebih cepat, notifikasi tepat waktu, dan pengamanan lebih nyaman.</p></div><button type="button" @click="installPwa">Instal</button></article>
      <p v-if="error" class="error">{{error}}</p>
      <article class="patient-medicine-card"><header><img src="/icons/calendar-color.png" alt=""/><div><h2>Jadwal Minum Obat Hari Ini</h2><p>{{new Date().toLocaleDateString('id-ID',{weekday:'long',day:'2-digit',month:'long',year:'numeric'})}}</p></div><b>Hari ini</b></header><div class="patient-medicine-body"><img src="/icons/pill-color.png" alt=""/><div><h3>{{hasReportedMedicationToday?'Anda Sudah Lapor Minum Obat Hari Ini':nextMedication?'Waktunya minum obat':'Jadwal obat belum tersedia'}}</h3><strong>{{hasReportedMedicationToday?'Laporan hari ini sudah tercatat':nextMedicationLabel}}</strong><p>{{hasReportedMedicationToday?'Terima kasih sudah melaporkan minum obat hari ini. Tetap ikuti jadwal berikutnya.':nextMedication?'Jangan lupa minum obat sesuai anjuran petugas kesehatan ya.':'Hubungi petugas bila jadwal obat belum tercatat.'}}</p></div></div><button v-if="!hasReportedMedicationToday" type="button" @click="nextMedication?openMedicationReport():openPatientPanel('medicine')"><img src="/icons/pill-color.png" alt=""/>{{nextMedication?'Lapor Minum Obat':'Lihat Informasi Obat'}} <span>→</span></button><button v-else type="button" @click="openPatientPanel('history')"><img src="/icons/chart-color.png" alt=""/>Lihat Laporan Hari Ini <span>→</span></button></article>
      <section class="patient-summary-cards"><button type="button" @click="openPatientPanel('history')"><header><img src="/icons/chart-color.png" alt=""/><div><b>Kepatuhan Minum Obat</b><small>{{medicationScheduleCount?`Jadwal hari ini: ${medicationScheduleCount} kali`:'Belum ada jadwal obat'}}</small></div></header><div><span>{{data.reports_today??0}} dari {{medicationScheduleCount}} laporan selesai</span><em>{{medicationProgress}}%</em></div></button><button type="button" @click="openPatientPanel('medicine')"><header><img src="/icons/pill-color.png" alt=""/><div><b>Obat Berikutnya</b><small>{{nextMedicationTime}}{{nextMedication?.time_of_day?' WIB':''}}</small></div></header><div class="next-medication-detail"><div><span>{{nextMedicationLabel}}</span><small>{{nextMedication ? `${nextMedicationDateLabel} · ${nextMedicationTime}${nextMedication.time_of_day?' WIB':''}` : 'Ikuti anjuran petugas kesehatan'}}</small></div></div></button></section>
      <section class="patient-info-cards"><button type="button" @click="openPatientPanel('schedules')"><header><img src="/icons/calendar-color.png" alt=""/><div><b>Jadwal Kontrol Berikutnya</b><small>{{ nextControl?.control_date ? formatDate(nextControl.control_date) : 'Belum ada jadwal kontrol' }}</small></div></header><p v-if="nextControl">{{nextControl.start_time?.slice(0,5)}} WIB<br/><small>{{nextControl.place_name}}</small></p><p v-else><small>Belum ada lokasi kontrol yang dijadwalkan.</small></p></button><article><header><img src="/icons/users-color.png" alt=""/><div><b>Kader PMO Anda</b><small>{{patient.cadre?.full_name ?? 'Belum ditetapkan'}}</small></div></header><button type="button" @click="openPatientPanel('cadre')">Hubungi Kader</button></article></section>
      <section class="patient-quick"><div class="patient-section-heading"><h2>Menu Cepat</h2><button type="button" @click="openPatientPanel('history')">Lihat Semua ›</button></div><div class="patient-quick-grid"><button type="button" @click="openPatientPanel('identity')"><i class="quick-blue"><img src="/icons/users-color.png" alt=""/></i>Data Pasien</button><button type="button" @click="openPatientPanel('history')"><i class="quick-teal"><img src="/icons/chart-color.png" alt=""/></i>Riwayat<br/>Laporan</button><button type="button" @click="openPatientPanel('sideEffects')"><i class="quick-pink"><img src="/icons/alert-color.png" alt=""/></i>Efek Samping</button><button type="button" @click="openPatientPanel('schedules')"><i class="quick-purple"><img src="/icons/calendar-color.png" alt=""/></i>Jadwal<br/>Kontrol</button><button type="button" @click="openPatientPanel('notifications')"><i class="quick-orange"><img src="/icons/notification-color.png" alt=""/></i>Notifikasi</button><button type="button" @click="openPatientPanel('profile')"><i class="quick-sky"><img src="/icons/settings-color.png" alt=""/></i>Profil</button></div></section>
    </section>
    <div v-if="reportDialog" class="report-dialog-backdrop" :class="{'report-dialog-backdrop--camera':reportStep==='camera'}" @click.self="closeReportDialog">
      <section class="report-dialog" :class="{'report-dialog--camera':reportStep==='camera'}" role="dialog" aria-modal="true" aria-label="Laporan minum obat">
        <template v-if="reportStep==='camera'"><div class="camera-fullscreen"><video v-if="cameraStream" ref="cameraVideo" autoplay playsinline muted :class="{mirrored:cameraFacing==='user'}"></video><div v-else class="camera-empty"><img src="/icons/pill-color.png" alt=""/><b>Kamera belum aktif</b><small>Izinkan akses kamera atau unggah foto dari perangkat.</small></div><div class="camera-topbar"><div><b>Foto bukti minum obat</b><small>{{cameraTimestamp}}</small></div><button type="button" aria-label="Tutup kamera" @click="closeReportDialog">×</button></div><p v-if="reportError" class="report-error camera-error">{{reportError}}</p><div class="camera-bottom-bar"><button v-if="cameraStream" type="button" class="camera-switch" @click="switchCamera" :aria-label="cameraFacing==='environment'?'Gunakan kamera depan':'Gunakan kamera belakang'">↻<small>{{cameraFacing==='environment'?'Depan':'Belakang'}}</small></button><button v-if="cameraStream" type="button" class="camera-shutter" @click="capturePhoto" aria-label="Ambil foto"><i></i></button><button v-else type="button" class="camera-switch" @click="startCamera">↻<small>Coba lagi</small></button><label class="camera-upload" aria-label="Unggah foto">▧<small>Unggah</small><input type="file" accept="image/jpeg,image/webp" capture="environment" @change="useSelectedPhoto"/></label></div></div></template>
        <template v-else>
        <header><div><span>Laporan Minum Obat</span><h2>{{reportStep==='effects'?'Cek efek samping':'Laporan terkirim'}}</h2></div><button type="button" aria-label="Tutup" @click="closeReportDialog">×</button></header>
        <div v-if="reportStep==='effects'" class="report-steps"><b class="active">1. Foto</b><i></i><b class="active">2. Efek samping</b></div>
        <template v-if="reportStep==='effects'"><p>Foto telah diambil. Apakah Anda merasakan efek samping setelah minum obat?</p><img class="report-photo-preview" :src="reportPhotoPreview" alt="Preview foto bukti minum obat"/><div class="effect-options"><button type="button" :class="{selected:hasSideEffect===false}" @click="hasSideEffect=false;reportError=''">Tidak ada efek samping</button><button type="button" :class="{selected:hasSideEffect===true}" @click="hasSideEffect=true;reportError=''">Ada efek samping</button></div><div v-if="hasSideEffect" class="effect-detail"><label>Kategori efek samping<select v-model="sideEffectCategory"><option value="" disabled>Pilih kategori</option><option value="mual">Mual atau muntah</option><option value="pusing">Pusing</option><option value="ruam">Ruam atau gatal</option><option value="lainnya">Lainnya</option></select></label><label>Ceritakan keluhan<textarea v-model="sideEffectDescription" placeholder="Jelaskan efek samping yang dirasakan"></textarea></label></div><p v-if="reportError" class="report-error">{{reportError}}</p><div class="report-submit-actions"><button type="button" class="retry-camera" @click="retakePhoto">Ambil ulang</button><button type="button" class="capture-button" :disabled="reportSaving" @click="submitMedicationReport">{{reportSaving?'Mengirim…':'Kirim laporan'}}</button></div></template>
        <template v-else><div class="report-success"><img src="/icons/chart-color.png" alt=""/><b>Laporan minum obat berhasil dikirim.</b><p>Terima kasih telah melaporkan pengobatan hari ini.</p><button type="button" class="capture-button" @click="closeReportDialog">Selesai</button></div></template>
        </template>
      </section>
    </div>
    <div v-if="historySideEffectDialog" class="report-dialog-backdrop" @click.self="closeHistorySideEffect">
      <section class="report-dialog" role="dialog" aria-modal="true" aria-label="Form efek samping">
        <header><div><span>Efek Samping Obat</span><h2>Form Laporkan / Ubah Efek Samping</h2></div><button type="button" aria-label="Tutup" @click="closeHistorySideEffect">×</button></header>
        <p style="font-size:12px;color:#527387;margin-bottom:12px">Sampaikan efek samping atau keluhan yang Anda rasakan setelah minum obat.</p>
        <div class="effect-detail" style="display:flex;flex-direction:column;gap:10px">
          <label>Kategori Efek Samping<select v-model="historySideEffectCategory"><option value="" disabled>Pilih kategori</option><option value="mual">Mual atau muntah</option><option value="pusing">Pusing</option><option value="ruam">Ruam atau gatal</option><option value="lainnya">Lainnya</option></select></label>
          <label>Ceritakan Keluhan<textarea v-model="historySideEffectDescription" placeholder="Jelaskan efek samping yang dirasakan"></textarea></label>
        </div>
        <p v-if="historySideEffectError" class="report-error" style="margin-top:8px">{{historySideEffectError}}</p>
        <div class="report-submit-actions" style="margin-top:14px">
          <button type="button" class="retry-camera" @click="closeHistorySideEffect">Batal</button>
          <button type="button" class="capture-button" :disabled="historySideEffectSaving" @click="submitHistorySideEffect">{{historySideEffectSaving?'Simpan…':'Simpan Efek Samping'}}</button>
        </div>
      </section>
    </div>
    <div v-if="patientPanel" class="patient-panel-backdrop" @click.self="closePatientPanel">
      <section class="patient-panel" role="dialog" aria-modal="true" :aria-label="patientPanelTitle">
        <header><div><span>Dashboard Pasien</span><h2>{{patientPanelTitle}}</h2></div><button type="button" aria-label="Tutup" @click="closePatientPanel">×</button></header>
        <template v-if="patientPanel==='medicine'"><p class="patient-panel-description">Gunakan pengingat ini untuk mengikuti jadwal minum obat hari ini.</p><div class="patient-panel-highlight"><img src="/icons/pill-color.png" alt=""/><div><b>{{nextMedicationLabel}}</b><small>{{nextMedication ? `${nextMedicationTime}${nextMedication.time_of_day ? ' WIB' : ''}${nextMedication.label && nextMedication.time_of_day ? ` · ${nextMedication.label}` : ''}` : 'Belum ada jadwal minum obat aktif.'}}</small></div></div><p class="patient-panel-note">Laporan minum obat memerlukan foto bukti serta lokasi perangkat Anda.</p><button v-if="nextMedication" type="button" class="patient-panel-action" @click="openMedicationReport">Mulai laporan minum obat</button></template>
        <template v-else-if="patientPanel==='identity'"><p class="patient-panel-description">Data identitas pasien yang tercatat di sistem.</p><dl class="patient-data-list"><div><dt>Nama</dt><dd>{{patient.full_name || name}}</dd></div><div><dt>NIK</dt><dd>{{patient.nik || 'Belum tersedia'}}</dd></div><div><dt>Jenis kelamin</dt><dd>{{patient.gender==='P'?'Perempuan':'Laki-laki'}}</dd></div><div><dt>No. HP</dt><dd>{{patient.phone || 'Belum tersedia'}}</dd></div><div><dt>Alamat</dt><dd>{{patient.full_address || 'Belum tersedia'}}</dd></div></dl></template>
        <template v-else-if="patientPanel==='history'"><p class="patient-panel-description">Riwayat laporan minum obat Anda.</p><div v-if="patientReports.length" class="patient-panel-list"><article v-for="item in patientReports" :key="item.id" style="flex-wrap:wrap"><img src="/icons/chart-color.png" alt=""/><div><b>{{formatDate(item.report_date)}}</b><small>{{item.scheduled_time?.slice(0,5) || 'Waktu tidak tercatat'}} · {{item.medication_taken?'Sudah minum obat':'Belum minum obat'}}</small></div><em :class="item.medication_taken?'patient-state--good':'patient-state--warning'">{{statusLabel(item.status)}}</em><div v-if="item.medication_taken" style="width:100%;margin-top:6px"><button type="button" class="patient-panel-action" style="padding:4px 10px;font-size:11px;margin:0" @click="openHistorySideEffect(item)">{{item.has_side_effect?'Ubah Efek Samping':'+ Tambah Efek Samping'}}</button></div></article></div><p v-else class="patient-panel-empty">Belum ada riwayat laporan minum obat.</p></template>
        <template v-else-if="patientPanel==='sideEffects'"><p class="patient-panel-description">Laporan efek samping obat yang tercatat.</p><div v-if="patientReports.filter(item=>item.has_side_effect).length" class="patient-panel-list"><article v-for="item in patientReports.filter(item=>item.has_side_effect)" :key="item.id" style="flex-wrap:wrap"><img src="/icons/alert-color.png" alt=""/><div><b>Efek samping tercatat</b><small>{{formatDate(item.report_date)}} · Status {{statusLabel(item.status)}}</small><div class="patient-side-effect-reason" style="margin-top:6px;font-size:12px;color:#852222;background:#fff5f5;padding:6px 10px;border-radius:6px;border:1px solid #ffdcdc"><b>Keluhan ({{ item.side_effect_category || 'Lainnya' }}):</b> {{ item.side_effect_description || 'Alasan keluhan belum dirinci.' }}</div></div></article></div><p v-else class="patient-panel-empty">Belum ada laporan efek samping obat.</p></template>
        <template v-else-if="patientPanel==='schedules'"><p class="patient-panel-description">Jadwal kontrol mendatang Anda.</p><div v-if="patientSchedules.length" class="patient-panel-list"><article v-for="item in patientSchedules" :key="item.id"><img src="/icons/calendar-color.png" alt=""/><div><b>{{formatDate(item.control_date)}} · {{item.start_time?.slice(0,5)}}</b><small>{{item.treatment_place_name}} · {{item.purpose || 'Kontrol rutin'}}</small></div><em class="patient-state--good">{{statusLabel(item.status)}}</em></article></div><p v-else class="patient-panel-empty">Belum ada jadwal kontrol mendatang.</p></template>
        <template v-else-if="patientPanel==='notifications'"><p class="patient-panel-description">Notifikasi terbaru akun Anda.</p><div v-if="notifications.length" class="patient-panel-list"><article v-for="item in notifications" :key="item.id"><img :src="item.is_read?'/icons/chart-color.png':'/icons/notification-color.png'" alt=""/><div><b>{{item.title}}</b><small>{{item.message}}</small></div></article></div><p v-else class="patient-panel-empty">Belum ada notifikasi baru.</p></template>
        <template v-else-if="patientPanel==='cadre'"><p class="patient-panel-description">Kader PMO yang ditugaskan untuk pendampingan pengobatan Anda.</p><div class="patient-panel-highlight"><img src="/icons/users-color.png" alt=""/><div><b>{{patient.cadre?.full_name || 'Belum ada kader yang ditugaskan'}}</b><small>{{patient.cadre?.phone || 'Nomor kader belum tersedia'}}</small></div></div><a v-if="patient.cadre?.phone" class="patient-panel-action" :href="`https://wa.me/${patient.cadre.phone}`" target="_blank" rel="noopener">Hubungi melalui WhatsApp</a></template>
        <template v-else-if="patientPanel==='profile'"><p class="patient-panel-description">Profil akun yang sedang digunakan.</p><div class="patient-panel-highlight"><img v-if="patientPhoto" class="patient-profile-photo" :src="patientPhoto" alt="Foto pasien"><span v-else class="patient-profile-fallback">{{initials}}</span><div><b>{{name}}</b><small>Pasien TB aktif</small></div></div><button type="button" class="patient-panel-logout" @click="logout">Logout</button></template>
      </section>
    </div>
    <nav class="patient-bottom-nav" aria-label="Navigasi pasien"><button type="button" :class="{selected:active==='Beranda'}" @click="closePatientPanel"><img src="/icons/home-color.png" alt=""/><span>Beranda</span></button><button type="button" :class="{selected:active==='Obat'}" @click="openPatientPanel('medicine')"><img src="/icons/pill-color.png" alt=""/><span>Obat</span></button><button type="button" :class="{selected:active==='Riwayat Laporan'}" @click="openPatientPanel('history')"><img src="/icons/chart-color.png" alt=""/><span>Laporan</span></button><button type="button" :class="{selected:active==='Kontrol'}" @click="openPatientPanel('schedules')"><img src="/icons/calendar-color.png" alt=""/><span>Kontrol</span></button><button type="button" :class="{selected:active==='Pengaturan'}" @click="openPatientPanel('profile')"><img src="/icons/settings-color.png" alt=""/><span>Pengaturan</span></button></nav>
  </main>
  <main v-else class="user-reference kader-reference">
    <header class="kader-header">
      <div class="kader-brand"><img class="kader-brand-mark" src="/icons/icon-512.png" alt="Empati TB"/><div><b>Empati TB</b><strong>Petukangan Utara</strong><small>Berbagi Bersama TB</small></div></div>
      <button type="button" class="kader-notification" aria-label="Notifikasi" @click="openPanel('information')"><img src="/icons/notification-color.png" alt=""/><i v-if="notifications.length">{{ notifications.length }}</i></button>
      <button type="button" class="kader-avatar" aria-label="Profil" @click="active='Profil'"><img v-if="cadrePhoto" class="kader-avatar-photo" :src="cadrePhoto" alt="Foto kader"/><template v-else>{{ cadreInitials }}</template></button>
    </header>

    <section class="kader-hero">
      <div class="kader-hero-content">
        <p>Halo, {{ kaderName }}</p>
        <small>Kader Empati TB</small>
        <div v-if="cadrePhoto" class="kader-hero-card">
          <div class="kader-hero-avatar-wrap">
            <img class="kader-hero-photo" :src="cadrePhoto" alt="Foto profil kader" />
          </div>
          <div class="kader-hero-meta">
            <b>{{ data.cadre?.full_name || user.name || 'Kader TB' }}</b>
            <span>Kader Aktif Wilayah Petukangan Utara</span>
          </div>
        </div>
      </div>
      <img src="/illustrations/kader-hero-team.png" alt="Kader dan tenaga kesehatan pendamping pasien TB" />
    </section>

    <section class="kader-content">
      <p v-if="error" class="error">{{error}}</p>
      <article class="kader-quote">“Setiap langkah kecil membuat perubahan besar untuk Indonesia bebas TB.”</article>

      <section class="kader-summary" aria-label="Ringkasan hari ini">
        <button type="button" class="summary-blue" @click="openPanel('patients')"><i><img src="/icons/users-color.png" alt=""/></i><strong>{{data.patients??0}}</strong><span>Pasien Aktif</span></button>
        <button type="button" class="summary-green" @click="openPanel('monitoring')"><i><img src="/icons/pill-color.png" alt=""/></i><strong>{{data.taken_today??0}}</strong><span>Sudah Minum Obat Hari Ini</span></button>
        <button type="button" class="summary-red" @click="openPanel('monitoring')"><i><img src="/icons/alert-color.png" alt=""/></i><strong>{{data.not_taken_today??0}}</strong><span>Tidak Minum</span></button>
        <button type="button" class="summary-purple" @click="openPanel('schedules')"><i><img src="/icons/calendar-color.png" alt=""/></i><strong>{{data.controls_today??0}}</strong><span>Jadwal Kontrol Hari Ini</span></button>
      </section>

      <section class="kader-menu-section">
        <div class="kader-section-heading"><h2>Menu Utama</h2><button type="button" @click="openPanel('reports')">Lihat Laporan</button></div>
        <div class="kader-menu-grid">
          <button v-for="menu in quickMenus" :key="menu.label" type="button" :class="['kader-menu-item', {selected: active===menu.label}]" @click="openPanel(menu.key)">
            <span :class="`menu-icon menu-icon--${menu.tone}`"><img :src="menu.icon" alt=""/><i v-if="menu.badge">{{menu.badge}}</i></span><b>{{menu.label}}</b>
          </button>
        </div>
      </section>

      <section class="kader-follow-up" :class="{visible: active==='Pasien'}">
        <div><span>Perlu ditindaklanjuti</span><b>{{ data.unreported_today??0 }} pasien belum mengirim laporan obat hari ini.</b></div>
        <button type="button" @click="openPanel('patients')">Lihat pasien</button>
      </section>

      <section class="kader-notification-section">
        <div class="kader-section-heading"><h2>Notifikasi Terbaru</h2><button type="button" @click="openPanel('information')">Lihat Semua</button></div>
        <div v-if="notifications.length" class="kader-notification-list">
          <article v-for="item in notifications" :key="item.id"><span :class="item.is_read?'notice-read':'notice-new'"><img :src="item.is_read?'/icons/chart-color.png':'/icons/alert-color.png'" alt=""/></span><div><b>{{item.title}}</b><p>{{item.message}}</p></div><time>{{formatTime(item.created_at)}}</time></article>
        </div>
        <p v-else class="kader-empty-notice">Belum ada notifikasi baru untuk Anda.</p>
      </section>
    </section>

    <div v-if="panel" class="kader-panel-backdrop" @click.self="closePanel">
      <section class="kader-panel" role="dialog" aria-modal="true" :aria-label="panelTitle">
        <header><div><span>Menu Kader</span><h2>{{ panelTitle }}</h2></div><button type="button" aria-label="Tutup" @click="closePanel">×</button></header>

        <template v-if="panel==='patients'">
          <p class="panel-description">Daftar pasien aktif yang menjadi binaan Anda. Pilih WhatsApp untuk menghubungi pasien.</p>
          <div v-if="cadrePatients.length" class="panel-list">
            <article v-for="item in cadrePatients" :key="item.id"><img src="/icons/users-color.png" alt=""/><div><b>{{ item.full_name }}</b><small>RT {{item.rt}} / RW {{item.rw}} · {{ Number(item.reports_today) ? 'Sudah melapor' : 'Belum melapor' }}</small></div><a :href="`https://wa.me/${item.phone}`" target="_blank" rel="noopener">WhatsApp</a></article>
          </div>
          <p v-else class="panel-empty">Belum ada pasien aktif yang ditugaskan kepada Anda.</p>
        </template>

        <template v-else-if="panel==='monitoring' || panel==='reports'">
          <div class="cadre-report-header-row">
            <p class="panel-description" style="margin:0">Monitoring status minum obat pasien binaan per tanggal.</p>
            <div class="cadre-date-picker-wrap">
              <label for="cadre-report-date-input">Pilih Tanggal:</label>
              <input id="cadre-report-date-input" type="date" v-model="cadreReportDate" @change="fetchCadreDailyReports(cadreReportDate)" class="cadre-date-input" />
              <button type="button" class="cadre-date-today-btn" @click="fetchCadreDailyReports(new Date().toISOString().slice(0, 10))">Hari Ini</button>
            </div>
          </div>

          <div class="panel-report-cards cadre-report-summary">
            <article :class="{active: cadreMonitoringFilter === 'all'}" @click="cadreMonitoringFilter = 'all'" style="cursor:pointer"><img src="/icons/users-color.png" alt=""/><b>{{cadreDailySummary.total}}</b><span>Total Pasien</span></article>
            <article :class="{active: cadreMonitoringFilter === 'taken'}" @click="cadreMonitoringFilter = 'taken'" style="cursor:pointer"><img src="/icons/pill-color.png" alt=""/><b>{{cadreDailySummary.taken}}</b><span>Sudah Minum</span></article>
            <article :class="{active: cadreMonitoringFilter === 'unreported'}" @click="cadreMonitoringFilter = 'unreported'" style="cursor:pointer"><img src="/icons/alert-color.png" alt=""/><b>{{cadreDailySummary.not_taken}}</b><span>Tidak Minum</span></article>
            <article :class="{active: cadreMonitoringFilter === 'unreported'}" @click="cadreMonitoringFilter = 'unreported'" style="cursor:pointer"><img src="/icons/monitoring-tb.png" alt=""/><b>{{cadreDailySummary.unreported}}</b><span>Belum Lapor</span></article>
          </div>

          <div class="cadre-monitoring-tab-filter">
            <button type="button" :class="{selected: cadreMonitoringFilter === 'all'}" @click="cadreMonitoringFilter = 'all'">Semua ({{ cadreDailySummary.total }})</button>
            <button type="button" :class="{selected: cadreMonitoringFilter === 'taken'}" @click="cadreMonitoringFilter = 'taken'">Sudah Minum ({{ cadreDailySummary.taken }})</button>
            <button type="button" :class="{selected: cadreMonitoringFilter === 'unreported'}" @click="cadreMonitoringFilter = 'unreported'">Belum Minum / Lapor ({{ Number(cadreDailySummary.not_taken) + Number(cadreDailySummary.unreported) }})</button>
          </div>

          <div class="cadre-daily-section">
            <div class="cadre-section-heading">
              <h3 style="font-size:14px;font-weight:700;color:#18363e;margin:0 0 8px">Status Pasien ({{ formatDate(cadreReportDate) }})</h3>
            </div>
            <div v-if="filteredCadreDailyPatients.length" class="panel-list">
              <article v-for="item in filteredCadreDailyPatients" :key="item.id" class="cadre-monitoring-row-clickable" @click="openCadrePatientDetail(item)">
                <img :src="item.daily_status === 'taken' ? '/icons/pill-color.png' : item.daily_status === 'not_taken' ? '/icons/alert-color.png' : '/icons/users-color.png'" alt=""/>
                <div style="flex:1">
                  <b>{{ item.full_name }}</b>
                  <small v-if="item.daily_status === 'taken'">
                    Sudah minum obat · Pukul {{ item.reported_time || item.scheduled_time || 'tercatat' }} WIB
                    <span v-if="item.has_side_effect" style="color:#d9534f;font-weight:600"> (Ada efek samping)</span>
                  </small>
                  <small v-else-if="item.daily_status === 'not_taken'" style="color:#d9534f">
                    Tidak minum obat<template v-if="item.not_taken_reason">: {{ item.not_taken_reason }}</template>
                  </small>
                  <small v-else style="color:#8c9b9e">
                    Belum ada laporan minum obat pada tanggal ini
                  </small>
                </div>
                <div style="display:flex;align-items:center;gap:6px">
                  <em :class="item.daily_status === 'taken' ? 'panel-status--good' : item.daily_status === 'not_taken' ? 'panel-status--warning' : 'panel-status--muted'">
                    {{ item.daily_status === 'taken' ? 'Sudah Minum' : item.daily_status === 'not_taken' ? 'Tidak Minum' : 'Belum Lapor' }}
                  </em>
                  <span class="cadre-row-chevron">›</span>
                </div>
              </article>
            </div>
            <p v-else class="panel-empty">Tidak ada pasien binaan pada kategori atau tanggal ini.</p>
          </div>
        </template>

        <template v-else-if="panel==='schedules'">
          <p class="panel-description">Jadwal kontrol mendatang dari pasien binaan Anda.</p>
          <div v-if="cadreSchedules.length" class="panel-list">
            <article v-for="item in cadreSchedules" :key="item.id"><img src="/icons/calendar-color.png" alt=""/><div><b>{{ item.full_name }}</b><small>{{ formatDate(item.control_date) }} · {{ item.start_time?.slice(0,5) }} · {{ item.treatment_place }}</small></div><em class="panel-status--good">{{ item.status }}</em></article>
          </div>
          <p v-else class="panel-empty">Belum ada jadwal kontrol mendatang.</p>
        </template>

        <template v-else-if="panel==='messages'">
          <p class="panel-description">Pilih pasien untuk mengirim pesan pengingat melalui WhatsApp.</p>
          <div v-if="cadrePatients.length" class="panel-list"><article v-for="item in cadrePatients" :key="item.id"><img src="/icons/notification-color.png" alt=""/><div><b>{{item.full_name}}</b><small>{{item.phone}}</small></div><a :href="`https://wa.me/${item.phone}`" target="_blank" rel="noopener">Kirim pesan</a></article></div>
          <p v-else class="panel-empty">Belum ada pasien yang dapat dihubungi.</p>
        </template>

        <template v-else-if="panel==='education'">
          <p class="panel-description">Materi singkat untuk pendampingan pasien TB.</p>
          <div class="education-list"><article><img src="/icons/pill-color.png" alt=""/><div><b>Ingatkan obat sesuai jadwal</b><p>Pastikan pasien minum obat sesuai anjuran dan melapor setiap hari.</p></div></article><article><img src="/icons/alert-color.png" alt=""/><div><b>Tindak lanjuti gejala efek samping</b><p>Arahkan pasien menghubungi petugas bila mengalami keluhan setelah minum obat.</p></div></article><article><img src="/icons/calendar-color.png" alt=""/><div><b>Pastikan hadir kontrol</b><p>Ingatkan jadwal kontrol agar pengobatan terus terpantau.</p></div></article></div>
        </template>

        <template v-else-if="panel==='information'">
          <p class="panel-description">Informasi dan notifikasi terbaru untuk kader.</p>
          <div v-if="notifications.length" class="panel-list"><article v-for="item in notifications" :key="item.id"><img :src="item.is_read?'/icons/chart-color.png':'/icons/alert-color.png'" alt=""/><div><b>{{item.title}}</b><small>{{item.message}}</small></div></article></div>
          <p v-else class="panel-empty">Belum ada informasi atau pengumuman baru.</p>
        </template>

        <template v-else-if="panel==='help'">
          <p class="panel-description">Butuh bantuan dalam mendampingi pasien?</p>
          <div class="education-list"><article><img src="/icons/notification-color.png" alt=""/><div><b>Hubungi petugas puskesmas</b><p>Gunakan menu Pesan Pasien atau koordinasikan tindak lanjut dengan petugas layanan TB.</p></div></article><article><img src="/icons/settings-color.png" alt=""/><div><b>Panduan penggunaan</b><p>Gunakan Data Pasien untuk melihat binaan, Monitoring untuk laporan obat, dan Jadwal untuk kontrol mendatang.</p></div></article></div>
        </template>

        <template v-else-if="panel==='profile'">
          <p class="panel-description">Informasi akun kader yang sedang digunakan.</p>
          <div class="profile-panel"><img v-if="cadrePhoto" class="kader-modal-photo" :src="cadrePhoto" alt="Foto kader"/><img v-else src="/icons/users-color.png" alt=""/><div><b>{{user.name || 'Kader TB'}}</b><small>Kader PMO</small></div></div>
          <button type="button" class="panel-primary panel-danger" @click="logout">Logout</button>
        </template>
      </section>
    </div>

    <div v-if="selectedCadreDailyPatient" class="cadre-patient-detail-backdrop" @click.self="closeCadrePatientDetail">
      <section class="cadre-patient-detail-modal" role="dialog" aria-modal="true" aria-label="Detail monitoring pasien">
        <header>
          <div><span>Detail Pasien</span><h2>{{ selectedCadreDailyPatient.full_name }}</h2></div>
          <button type="button" aria-label="Tutup detail pasien" @click="closeCadrePatientDetail">×</button>
        </header>
        <div class="cadre-detail-status" :class="`status-${selectedCadreDailyPatient.daily_status}`">
          <img :src="selectedCadreDailyPatient.daily_status === 'taken' ? '/icons/pill-color.png' : selectedCadreDailyPatient.daily_status === 'not_taken' ? '/icons/alert-color.png' : '/icons/users-color.png'" alt=""/>
          <div><small>Status {{ formatDate(cadreReportDate) }}</small><b>{{ selectedCadreDailyPatient.daily_status === 'taken' ? 'Sudah Minum Obat' : selectedCadreDailyPatient.daily_status === 'not_taken' ? 'Tidak Minum Obat' : 'Belum Lapor' }}</b></div>
        </div>
        <dl class="cadre-detail-grid">
