          <div><dt>Waktu laporan</dt><dd>{{ selectedCadreDailyPatient.reported_time ? selectedCadreDailyPatient.reported_time + ' WIB' : 'Belum ada laporan' }}</dd></div>
          <div><dt>Lokasi pasien</dt><dd>{{ selectedCadreDailyPatient.rt || selectedCadreDailyPatient.rw ? `RT ${selectedCadreDailyPatient.rt || '-'} / RW ${selectedCadreDailyPatient.rw || '-'}` : (selectedCadreDailyPatient.full_address || selectedCadreDailyPatient.address || 'Belum tersedia') }}</dd></div>
          <div><dt>Nomor telepon</dt><dd>{{ selectedCadreDailyPatient.phone || 'Belum tersedia' }}</dd></div>
        </dl>
        <div v-if="selectedCadreDailyPatient.not_taken_reason" class="cadre-detail-note warning"><b>Alasan tidak minum</b><p>{{ selectedCadreDailyPatient.not_taken_reason }}</p></div>
        <div v-if="selectedCadreDailyPatient.has_side_effect" class="cadre-detail-note danger"><b>Efek samping</b><p>{{ selectedCadreDailyPatient.side_effect_category || 'Keluhan efek samping' }}<template v-if="selectedCadreDailyPatient.side_effect_description"> · {{ selectedCadreDailyPatient.side_effect_description }}</template></p></div>
        <div v-if="selectedCadreDailyPatient.verification_note" class="cadre-detail-note"><b>Catatan petugas</b><p>{{ selectedCadreDailyPatient.verification_note }}</p></div>
        <div class="cadre-detail-actions">
          <button type="button" class="cadre-detail-close" @click="closeCadrePatientDetail">Tutup</button>
          <a v-if="selectedCadreDailyPatient.phone" :href="`https://wa.me/${String(selectedCadreDailyPatient.phone).replace(/\D/g, '')}`" target="_blank" rel="noopener">Hubungi WhatsApp</a>
        </div>
      </section>
    </div>

    <nav class="kader-bottom-nav" aria-label="Navigasi kader">
      <button type="button" :class="{selected:active==='Beranda'}" @click="closePanel"><i><img src="/icons/home-color.png" alt=""/></i><span>Beranda</span></button>
