      <button type="button" :class="{selected:active==='Jadwal Kontrol'}" @click="openPanel('schedules')"><i><img src="/icons/calendar-color.png" alt=""/></i><span>Jadwal</span></button>
      <button type="button" :class="{selected:active==='Profil'}" @click="openPanel('profile')"><i><img src="/icons/settings-color.png" alt=""/></i><span>Profil</span></button>
    </nav>
